// EASEIT - Entrée unifiée : authentification, limitation de débit, normalisation, guardrails (couche 1)
const sd = $getWorkflowStaticData('global');
const h = $json.headers || {};
const b = $json.body || {};
const actor = b.actor || {};
const role = String(actor.role || '').toUpperCase();
const actorEmail = String(actor.email || '').trim().toLowerCase().slice(0, 120);
const allowedRoles = ['RECRUITER', 'HR_MANAGER', 'ADMIN', 'EMPLOYEE'];
const user = allowedRoles.includes(role) && Number.isInteger(Number(actor.id)) && actorEmail.includes('@')
  ? { role, user: actorEmail, employee_id: actor.employee_id || (role === 'EMPLOYEE' ? String(actor.id) : null) }
  : null;
const now = Date.now();

// --- limitation de débit (60/min authentifié, 5/min anonyme) ---
sd.rate = sd.rate || {};
const key = user ? user.user : 'anon:' + String(h['x-forwarded-for'] || h['host'] || 'x');
sd.rate[key] = (sd.rate[key] || []).filter(t => now - t < 60000);
sd.rate[key].push(now);
const limit = user ? 60 : 5;

// --- guardrails : nettoyage Unicode + motifs d'injection ---
const ZW = /[\u200b\u200c\u200d\u2060\ufeff]/g;
const PATTERNS = [
  /ignore (all )?(the )?(previous|prior|above) instructions/i, /disregard (all )?(previous|prior)/i,
  /system prompt/i, /you are now/i, /send (an? )?e-?mail/i, /highest score/i,
  /give (me|this candidate)/i, /ignor(e|ez)\s+(toutes?\s+)?(les\s+)?instructions/i,
  /note maximale/i, /envoie[rz]?\s+(un\s+)?(mail|e-?mail)/i, /score\s*(de\s*)?100\b/i
];
function sanitize(t, max) {
  let s = String(t == null ? '' : t);
  s = s.normalize('NFKC').replace(ZW, '').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, ' ').replace(/<[^>]*>/g, ' ');
  const truncated = s.length > max;
  return { text: s.slice(0, max), truncated };
}
const subj = sanitize(b.subject, 200);
const body = sanitize(b.body, 20000);
const cv = sanitize(b.cv_text, 12000);
const contextDocs = Array.isArray(b.context_docs) ? b.context_docs.slice(0, 20).map(doc => ({
  id: String(doc.id || '').slice(0, 100), title: sanitize(doc.title, 200).text,
  text: sanitize(doc.text, 5000).text, audience: 'employee'
})).filter(doc => doc.id && doc.text) : [];
const flags = [];
const all = [subj.text, body.text, cv.text].join('\n');
if (PATTERNS.some(p => p.test(all))) flags.push('PROMPT_INJECTION_SUSPECTED');
const rawAll = String(b.subject || '') + String(b.body || '') + String(b.cv_text || '');
if (new RegExp('[\\u200b\\u200c\\u200d\\u2060\\ufeff]').test(rawAll)) flags.push('HIDDEN_CHARACTERS_REMOVED');
if (/<[a-z][^>]*>/i.test(rawAll)) flags.push('HTML_STRIPPED');
if (body.truncated || cv.truncated) flags.push('TRUNCATED');

// --- autorisation (RBAC) ---
const source = String(b.source || 'email').slice(0, 30);
let authorized = true, deny = '', status = 200;
if (!user) { authorized = false; deny = 'AUTHENTICATION_FAILED'; status = 401; }
else if (sd.rate[key].length > limit) { authorized = false; deny = 'RATE_LIMITED'; status = 429; }
else if (source === 'employee_portal' && user.role !== 'EMPLOYEE') { authorized = false; deny = 'ROLE_NOT_ALLOWED_FOR_SOURCE'; status = 403; }
else if (source !== 'employee_portal' && !['RECRUITER', 'HR_MANAGER', 'ADMIN'].includes(user.role)) { authorized = false; deny = 'ROLE_NOT_ALLOWED_FOR_SOURCE'; status = 403; }
else if (!subj.text && !body.text && !cv.text) { authorized = false; deny = 'EMPTY_MESSAGE'; status = 422; }

const id = 'MSG-' + now.toString(36).toUpperCase() + Math.floor(Math.random() * 1296).toString(36).toUpperCase();
const message = {
  id, request_id: String(b.request_id || '').slice(0, 100), source, context_docs: contextDocs,
  sender: String(b.sender || '').toLowerCase().slice(0, 120),
  subject: subj.text, body: body.text, cv_text: cv.text,
  has_attachment: !!b.has_attachment || cv.text.length > 0,
  candidate_name: String(b.candidate_name || '').replace(/[^\p{L}\s'’-]/gu, '').slice(0, 60),
  candidate_id: String(b.candidate_id || '').replace(/[^A-Za-z0-9-]/g, '').slice(0, 20),
  job_id: String(b.job_id || 'JOB-001').replace(/[^A-Za-z0-9-]/g, '').slice(0, 20),
  received_at: new Date(now).toISOString()
};
const out = {
  message, user: user ? { role: user.role, user: user.user, employee_id: user.employee_id || null } : null,
  security_flags: flags, quarantined: flags.includes('PROMPT_INJECTION_SUSPECTED'),
  authorized, deny_reason: deny, http_status: status, _audit: null
};
if (!authorized) {
  out._audit = { user: user ? user.user : 'anonymous', agent: 'gateway', action: 'ACCESS_DENIED', entity: 'request', entity_id: id, details: { reason: deny, source } };
  out.response = { status: 'DENIED', reason: deny };
}
return { json: out };

// EASEIT - Audit Service : journal append-only à hachage chaîné (SHA-256), stocké dans les static data du workflow
function sha256(str) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
