const sd = $getWorkflowStaticData('global');
sd.audit = sd.audit || [];
const list = $json._audit ? (Array.isArray($json._audit) ? $json._audit : [$json._audit]) : [];
if ($json._record) {
  sd.messages = sd.messages || [];
  sd.messages.push($json._record);
  if (sd.messages.length > 500) sd.messages = sd.messages.slice(-500);
}
let last = null;
for (const ev of list) {
  const prev = sd.audit.length ? sd.audit[sd.audit.length - 1].hash : 'GENESIS';
  const body = JSON.parse(JSON.stringify({
    id: sd.audit.length + 1,
    user: ev.user || ($json.user && $json.user.user) || 'system',
    agent: ev.agent || 'system', action: ev.action,
    entity: ev.entity || null, entity_id: ev.entity_id || null,
    details: ev.details || {}, model: ev.model || null, ts: new Date().toISOString()
  }));
  const hash = sha256(prev + stable(body));
  sd.audit.push(Object.assign({}, body, { prev_hash: prev, hash }));
  last = hash;
}
const out = Object.assign({}, $json, { _audit: null, _record: null });
if (last) out.audit_hash = last.slice(0, 12);
return { json: out };

// EASEIT - Planner : règles d'abord (le LLM n'est appelé que si aucune règle n'atteint 0,8)
