const text = (m.subject + ' ' + m.body).toLowerCase();
const hasAttach = m.has_attachment;
const KNOWN_AWAITING = ['karim.benali@example.com', 'sonia.jlassi@example.com'];
const mk = (category, intent, priority, destination, confidence, reason, department = null) => ({ category, intent, priority, destination, confidence, reason, department, source: 'RULES' });
const rules = [
  // R0 : demandes de données globales/sensibles -> revue humaine
  { re: /(liste (de )?tous les candidats|all candidates|salaire (de|du|d'un)|salary of|mot de passe|password)/i, when: true,
    res: mk('OTHER', 'OTHER', 'URGENT', 'HUMAN_REVIEW', 0.9, 'Demande de données globales ou sensibles : revue humaine') },
  // R1 : candidature avec pièce jointe
  { re: /(candidature|poste|\bcv\b|application|apply)/i, when: hasAttach,
    res: mk('RECRUITMENT', 'NEW_APPLICATION', 'MEDIUM', 'ATS_AGENT', 0.9, 'Pièce jointe + vocabulaire de candidature') },
  // R2 : demande de replanification
  { re: /(reporter|décaler|decaler|changer l'heure|indisponible|reschedule)/i, when: /(entretien|interview)/i.test(text),
    res: mk('RECRUITMENT', 'INTERVIEW_CHANGE', 'URGENT', 'URGENT_AGENT', 0.9, 'Demande de report d\'entretien') },
  // Training and IT requests stay in the human queue with a responsible department.
  { re: /(training|formation|cours|course)/i, when: true,
    res: mk('TRAINING', 'TRAINING_REQUEST', 'MEDIUM', 'HUMAN_REVIEW', 0.95, 'Demande de formation ? valider par les RH', 'HR') },
  { re: /(professional account|account access|cannot access|can't access|unable to access|cannot log in|can't log in|compte professionnel|acc[e?]s.{0,30}compte)/i, when: true,
    res: mk('DEPARTMENT_REQUEST', 'IT_ACCESS_REQUEST', 'MEDIUM', 'HUMAN_REVIEW', 0.95, 'Demande d?acc?s ? orienter vers le support informatique', 'IT') },
  // R3 : réponse courte d'un candidat connu en attente
  { re: /(confirme|d'accord|ok pour|confirm)/i, when: KNOWN_AWAITING.includes(m.sender) && text.length < 200,
    res: mk('RECRUITMENT', 'FOLLOW_UP_REPLY', 'MEDIUM', 'HUMAN_REVIEW', 0.85, 'Réponse d\'un candidat en attente : validation humaine') },
  // R5 (évaluée avant R4) : plainte / urgence côté employé
  { re: /(plainte|harc[eè]lement|urgent|imm[eé]diatement)/i, when: m.source === 'employee_portal',
    res: mk('EMPLOYEE', 'OTHER', 'URGENT', 'HUMAN_REVIEW', 0.9, 'Plainte ou urgence employé : escalade humaine') },
  // R4 : question employé
  { re: /(cong[eé]|paie|t[eé]l[eé]travail|attestation|solde|frais|horaires?|onboarding)/i, when: true,
    res: null },
  { re: /(.)/, when: m.source === 'employee_portal', res: null }
];
let planner = null;
for (const r of rules) {
  if (r.res && r.when && r.re.test(text)) { planner = r.res; break; }
}
if (!planner && (m.source === 'employee_portal' || /(cong[eé]|paie|t[eé]l[eé]travail|attestation|solde|frais)/i.test(text))) {
  const personal = /(mon solde|mes cong[eé]s|solde (de )?cong|my (leave|balance)|solde de)/i.test(text);
  planner = mk('EMPLOYEE', personal ? 'PERSONAL_DATA_REQUEST' : 'POLICY_QUESTION', 'INFORMATION', 'EMPLOYEE_AGENT', 0.85, personal ? 'Question personnelle employé' : 'Question de politique RH');
}
if (planner && !planner.department && ['RECRUITMENT', 'EMPLOYEE'].includes(planner.category)) planner.department = 'HR';
return { json: Object.assign({}, $json, { planner, planner_ready: !!(planner && planner.confidence >= 0.8) }) };

// EASEIT - Validation stricte de la sortie du LLM Planner (équivalent Pydantic : énumérations fermées)
const orig = $('Planner - règles').item.json;
let raw = String($json.output == null ? '' : $json.output).replace(/```json|```/g, '').trim();
let p = null;
try { p = JSON.parse(raw); } catch (e) {
  const mm = raw.match(/\{[\s\S]*\}/);
  if (mm) { try { p = JSON.parse(mm[0]); } catch (e2) { p = null; } }
}
const CAT = ['RECRUITMENT', 'EMPLOYEE', 'TRAINING', 'DEPARTMENT_REQUEST', 'OTHER'];
const INT = ['NEW_APPLICATION', 'INTERVIEW_CHANGE', 'FOLLOW_UP_REPLY', 'POLICY_QUESTION', 'PERSONAL_DATA_REQUEST', 'TRAINING_REQUEST', 'IT_ACCESS_REQUEST', 'OTHER'];
const PRI = ['URGENT', 'MEDIUM', 'INFORMATION', 'LOW'];
const DEST = ['ATS_AGENT', 'URGENT_AGENT', 'EMPLOYEE_AGENT', 'HUMAN_REVIEW'];
const DEP = ['HR', 'IT', 'FINANCE', 'MARKETING', 'SALES', 'OTHER'];
const ok = p && CAT.includes(p.category) && INT.includes(p.intent) && PRI.includes(p.priority) &&
  DEST.includes(p.destination) && (p.department == null || DEP.includes(p.department)) && typeof p.confidence === 'number' && p.confidence >= 0 && p.confidence <= 1;
let planner;
if (!ok) {
  planner = { category: 'OTHER', intent: 'OTHER', priority: 'MEDIUM', destination: 'HUMAN_REVIEW', confidence: 0, reason: 'Sortie LLM invalide : repli sur revue humaine', department: 'OTHER', source: 'LLM' };
} else {
  planner = { category: p.category, intent: p.intent, priority: p.priority, destination: p.destination,
    confidence: p.confidence, reason: String(p.reason || '').slice(0, 200), department: p.department || null, source: 'LLM' };
  if (planner.confidence < 0.6) {
    planner.destination = 'HUMAN_REVIEW';
    planner.reason = ('Confiance < 0,6 : revue humaine. ' + planner.reason).slice(0, 200);
  }
}
return { json: Object.assign({}, orig, { planner }) };

// EASEIT - Finalisation du Planner : règle de quarantaine + événements d'audit + enregistrement pour le digest
const planner = Object.assign({}, $json.planner);
const m = $json.message;
const flags = $json.security_flags || [];
if (flags.includes('PROMPT_INJECTION_SUSPECTED') && planner.destination !== 'ATS_AGENT') {
  planner.destination = 'HUMAN_REVIEW';
  planner.reason = ('Contenu suspect (injection) : revue humaine. ' + planner.reason).slice(0, 200);
}
const domain = (m.sender.split('@')[1] || 'inconnu');
const events = [
  { agent: 'gateway', action: 'MESSAGE_RECEIVED', entity: 'message', entity_id: m.id,
    details: { source: m.source, sender_domain: domain, body_chars: m.body.length, cv_chars: m.cv_text.length, flags } },
  { agent: 'planner', action: 'MESSAGE_CLASSIFIED', entity: 'message', entity_id: m.id,
    model: planner.source === 'LLM' ? 'llama3.2:3b' : null, details: planner }
];
if (flags.length) events.push({ agent: 'guardrails', action: 'SUSPICIOUS_CONTENT_DETECTED', entity: 'message', entity_id: m.id, details: { flags, quarantined: flags.includes('PROMPT_INJECTION_SUSPECTED') } });
const human = ['INTERVIEW_CHANGE', 'OTHER'].includes(planner.intent) && planner.category !== 'EMPLOYEE' || planner.destination === 'HUMAN_REVIEW' || planner.priority === 'URGENT' || planner.confidence < 0.6;
const record = { id: m.id, received_at: m.received_at, sender_domain: domain, subject: m.subject.slice(0, 120), snippet: (m.body || m.cv_text).slice(0, 400),
  category: planner.category, intent: planner.intent, priority: planner.priority, destination: planner.destination, confidence: planner.confidence, needs_human_reply: !!human, flags };
return { json: Object.assign({}, $json, { planner, _audit: events, _record: record }) };

