L.push('RAPPORT ATS - ' + ev.job_title + ' (' + ev.job_id + ')');
L.push('Message : ' + $json.message.id + ' | Candidat : ' + ($json.message.candidate_id || 'n/c'));
if (flags.length) L.push('*** ALERTE SÉCURITÉ : ' + flags.join(', ') + (flags.includes('PROMPT_INJECTION_SUSPECTED') ? ' - CONTENU EN QUARANTAINE, AUCUNE ACTION AUTOMATIQUE ***' : ' ***'));
L.push('');
if (ev.status !== 'OK') {
  L.push(ev.band);
} else {
  L.push('SCORE GLOBAL : ' + ev.score + ' / 100 - ' + ev.band + ' (indicateur d\'aide à la décision, jamais une décision)');
  L.push('');
  L.push('DÉTAIL PAR CRITÈRE (poids | correspondance | contribution)');
  Object.keys(ev.breakdown).forEach(k => { const b = ev.breakdown[k]; L.push('- ' + k + ' : ' + b.weight + ' | ' + b.match + ' | ' + b.contribution + ' pts'); });
  L.push('');
  L.push('PREUVES VÉRIFIÉES (extrait exact du CV)');
  ev.evidence.slice(0, 15).forEach(e => L.push('- [' + e.type + '] ' + e.value + ' : "' + e.quote.slice(0, 90) + '"'));
  L.push('');
  L.push('INFORMATIONS ABSENTES / NON VÉRIFIÉES');
  (ev.missing.length ? ev.missing : ['Aucune']).forEach(x => L.push('- ' + x));
}
L.push('');
L.push('CRITÈRES IGNORÉS VOLONTAIREMENT : ' + ev.ignored_criteria.join(', '));
L.push('ANONYMISATION : ' + JSON.stringify($json.ats.masked));
L.push('VERSIONS : modèle ' + ev.versions.model + ' | prompt ' + ev.versions.prompt + ' | scoring ' + ev.versions.scoring + ' | ' + ev.versions.date);
const text = L.join('\n');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
return { json: Object.assign({}, $json, { report_text: text, report_html: esc(text) }) };

// EASEIT - Décision du recruteur -> contexte de brouillon (aucun envoi ici)
const ctx = $('Rapport recruteur').item.json;
const dec = String($json['Décision'] || '');
const user = ctx.user || null;
const m = ctx.message;
const base = Object.assign({}, ctx, { create_draft: false });
if (!user || user.role !== 'RECRUITER') {
  return { json: Object.assign(base, { _audit: { user: 'anonymous', agent: 'approval-engine', action: 'ACCESS_DENIED', entity: 'message', entity_id: m.id, details: { reason: 'RECRUITER_TOKEN_REQUIRED', decision: dec } } }) };
}
const MAP = { 'Inviter à un entretien': 'INVITATION', 'Demander un complément': 'DEMANDE_INFO', 'Rejeter': 'REFUS' };
const kind = MAP[dec];
if (!kind) {
  return { json: Object.assign(base, { _audit: { user: user.user, agent: 'recruiter', action: 'RECRUITER_DECISION', entity: 'message', entity_id: m.id, details: { decision: dec || 'AUCUNE (expiration ou attente)' } } }) };
}
const id = m.candidate_id || ('CAND-' + (parseInt(m.id.slice(-3), 36) % 900 + 100));
return { json: Object.assign(base, {
  create_draft: true, draft_kind: kind,
  candidate: { id, name: m.candidate_name || 'Madame, Monsieur', email: m.sender },
  job_title: ctx.evaluation.job_title, slots: [], origin: 'ATS', requested_by: user.user,
  pre_events: [{ user: user.user, agent: 'recruiter', action: 'RECRUITER_DECISION', entity: 'message', entity_id: m.id, details: { decision: dec, draft_kind: kind } }]
}) };
